function renderTarot(){let slots=$('selectedSlots'),deck=$('cardDeck');for(let i=0;i<3;i++){let card=tarotSelected[i],slot=slots.children[i];if(!slot){slot=document.createElement('div');slots.append(slot)}let key=card?`${card.id}:${card.isReversed}`:'empty';if(slot.dataset.cardKey!==key){slot.dataset.cardKey=key;slot.className='tarot-slot'+(card?' filled':'');slot.replaceChildren();let cap=document.createElement('small');cap.textContent=['第一张','第二张','第三张'][i];slot.append(cap);if(card){let name=document.createElement('b');name.textContent=card.name;let state=document.createElement('small');state.textContent=card.isReversed?'逆位':'正位';slot.append(name,state)}else{let p=document.createElement('span');p.textContent='待抽取';slot.append(p)}}}deck.replaceChildren();visibleDeck().forEach((card,i)=>{const b=document.createElement('button');b.className='tarot-card'+(i===highlightIndex?' highlight':'')+(i===lockedIndex?' locked':'');b.setAttribute('aria-label',`选择第 ${deckOffset+i+1} 张牌`);let startX=0,startY=0,moved=false;b.onpointerdown=e=>{if(tarotSelected.length>=3)return;b.setPointerCapture(e.pointerId);startX=e.clientX;startY=e.clientY;moved=false;b.classList.add('dragging')};b.onpointermove=e=>{if(!b.hasPointerCapture(e.pointerId))return;let dx=e.clientX-startX,dy=e.clientY-startY;if(Math.hypot(dx,dy)>8)moved=true;if(moved)b.style.transform=`translate(${dx*.85}px,${dy*.85}px)`};b.onpointerup=e=>{b.classList.remove('dragging');b.style.transform='';let box=$('selectedSlots').getBoundingClientRect();let over=e.clientX>=box.left-40&&e.clientX<=box.right+40&&e.clientY>=box.top-40&&e.clientY<=box.bottom+40;if(!moved||over)drawCard(deckOffset+i);else $('tarotStatus').textContent='请把牌拖到上方牌位，或直接点击选牌。'};b.onpointercancel=()=>{b.classList.remove('dragging');b.style.transform=''};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();drawCard(deckOffset+i)}};deck.append(b)})}
