$('prevCards').onclick=()=>{deckOffset=Math.max(0,deckOffset-displayCount);highlightIndex=0;lockedIndex=null;gesturePhase='scan';renderTarot()};$('nextCards').onclick=()=>{deckOffset=Math.min(Math.max(0,tarotDeck.length-displayCount),deckOffset+displayCount);highlightIndex=0;lockedIndex=null;gesturePhase='scan';renderTarot()};$('restartTarot').onclick=()=>{shuffleCards()};$('tarotExit').onclick=()=>{closeTarot();$('insideStatus').textContent='想再抽一次牌，可以在这里重新开始。';$('reopenTarot').classList.remove('hidden')};$('reopenTarot').onclick=()=>{ $('reopenTarot').classList.add('hidden');openTarot()};const zodiacInfo={白羊座:['火象','想做就会想尽快推进，但这次先看清牌里提醒你的阻力，别一着急把话说满。'],金牛座:['土象','你可能更在意事情能不能落到实处。把牌里的提示放到现实条件里看，算一算时间、成本和自己的底线。'],双子座:['风象','你可能会从好几个角度想这件事。牌里哪一句最让你在意？先抓住那个问题，不必同时想完所有可能。'],巨蟹座:['水象','你可能很在乎这件事里的人和感受。照顾别人的同时，也问问自己是不是已经有点委屈。'],狮子座:['火象','你可能希望事情有个清楚的回应。可以主动争取，但别为了证明自己，把别人的态度都扛在身上。'],处女座:['土象','你可能已经把细节想了很多遍。牌里提醒的事可以逐项核实，但不必等到一切完美才行动。'],天秤座:['风象','你可能正反两面都看得到。听完牌的意思，再问问自己：如果不用照顾所有人的想法，你会选什么？'],天蝎座:['水象','你可能很在意事情背后真正的意思。直觉可以留着，但涉及对方想法时，最好还是找机会问清楚。'],射手座:['火象','你可能不想一直困在原地。如果牌里说要等等，可以把等待变成准备，同时给自己留一条新路。'],摩羯座:['土象','你可能习惯先考虑责任和结果。把目标拆成眼前能做的一步，也给自己留一点喘息的空间。'],水瓶座:['风象','你可能会从自己的角度重新看问题。牌里哪一处让你觉得不对劲？那个疑问值得你继续追问。'],双鱼座:['水象','你可能对气氛和别人的态度很敏感。感受可以相信一半，另一半交给事实和对方持续的行动。']};
