function switchReadingPage(page,fromGesture=false){readingPage=Math.max(0,Math.min(3,page));const out=$('tarotReading');out.querySelectorAll('[data-page]').forEach(el=>{const active=Number(el.dataset.page)===readingPage;el.classList.toggle('is-active',active);el.setAttribute('aria-pressed',String(active))});out.querySelectorAll('[data-pane]').forEach(el=>{el.hidden=Number(el.dataset.pane)!==readingPage});if(fromGesture)playEffect('flip')}
