let handsInstance=null,handLoading=null,handBusy=false,lastInference=0;
function loadHands(){if(window.Hands)return Promise.resolve();if(handLoading)return handLoading;handLoading=new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='mediapipe/hands.js';s.onload=resolve;s.onerror=()=>{handLoading=null;reject(Error('识别组件加载失败'))};document.head.append(s)});return handLoading}
function panel(){return activeMode==='fortune'?$('fortuneGesturePanel'):$('gesturePanel')}function status(){return activeMode==='fortune'?$('fortuneGestureStatus'):$('gestureStatus')}function videoEl(){return activeMode==='fortune'?$('fortuneVideo'):$('cameraVideo')}function toggle(){return activeMode==='fortune'?$('fortuneGestureToggle'):$('gestureToggle')}
async function startCamera(){if(activeMode==='tarot'&&!tarotLive)return;const generation=++handGeneration;const mode=activeMode;toggle().disabled=true;panel().classList.remove('hidden');status().textContent='请允许摄像头，然后将手放进画面。';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('浏览器不支持摄像头');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});if(generation!==handGeneration){stream.getTracks().forEach(t=>t.stop());return}handStream=stream;videoEl().srcObject=stream;await videoEl().play();toggle().textContent='关闭摄像头';status().textContent='摄像头已开启，正在准备本地手势识别…';await loadHands();if(generation!==handGeneration)return;const hands=new window.Hands({locateFile:file=>'mediapipe/'+file});handsInstance=hands;hands.setOptions({maxNumHands:1,modelComplexity:0,minDetectionConfidence:.6,minTrackingConfidence:.6});hands.onResults(onHands);await hands.initialize();if(generation!==handGeneration){hands.close();return}status().textContent=mode==='tarot'?'张开手掌左右选牌，握拳锁定，再张开确认。':'先握拳并左右晃动，再张开手掌抽签。';gesturePhase='scan';fortunePhase='scan';candidate='';lastInference=0;handLoop()}catch(e){if(generation!==handGeneration)return;const message=e.name==='NotAllowedError'?'摄像头权限被拒绝，请在浏览器设置中允许后重试。':e.name==='NotFoundError'?'没有找到摄像头，请检查设备连接。':'识别启动失败：'+(e.message||'请检查浏览器');stopCamera();panel().classList.remove('hidden');status().textContent=message}finally{toggle().disabled=false}}
function fingersUp(h){let count=0;for(const [tip,pip] of [[8,6],[12,10],[16,14],[20,18]]){let dist=p=>Math.hypot(p.x-h[0].x,p.y-h[0].y,p.z-h[0].z);if(dist(h[tip])>dist(h[pip])*1.12)count++}return count}
function drawHandOverlay(h){const canvas=$(activeMode==='fortune'?'fortuneHandOverlay':'cameraHandOverlay');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);if(!h)return;const lines=[[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17]];ctx.lineWidth=3;ctx.strokeStyle='rgba(255,220,157,.86)';for(const line of lines){ctx.beginPath();line.forEach((i,j)=>{const x=h[i].x*canvas.width,y=h[i].y*canvas.height;if(j===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke()}ctx.fillStyle='#fff1c7';h.forEach(p=>{ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,4,0,Math.PI*2);ctx.fill()})}
function onHands(results){const h=results.multiHandLandmarks?.[0],now=performance.now();drawHandOverlay(h);if(!h){candidate='';status().textContent='请把一只手放到镜头中央。';return}const up=fingersUp(h),name=up>=3?'open':up<=1?'fist':'other';if(name!==candidate){candidate=name;candidateSince=now}const stable=now-candidateSince>=220;if(activeMode==='tarot'){if(!$('tarotReading').classList.contains('hidden')){if(name==='open'&&stable){readingGestureReady=true;let idx=Math.min(3,Math.max(0,Math.floor((1-h[9].x)*4)));if(idx!==readingHover){readingHover=idx;$('tarotReading').querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('hand-hover',Number(el.dataset.page)===idx))}status().textContent='移动手掌选解读，握拳打开。'}else if(name==='fist'&&stable&&readingGestureReady&&now-readingLastAction>800){readingGestureReady=false;readingLastAction=now;switchReadingPage(readingHover,true);status().textContent='已打开，张开手掌可继续选择。'}return}if(tarotSelected.length>=3)return;if(now-lastDraw<800)return;if(gesturePhase==='scan'&&name==='open'){let n=visibleDeck().length,idx=Math.min(n-1,Math.max(0,Math.floor((1-h[9].x)*n)));if(idx!==highlightIndex){highlightIndex=idx;renderTarot()}status().textContent='张开手掌左右选牌，握拳锁定。'}if(gesturePhase==='scan'&&name==='fist'&&stable){lockedIndex=highlightIndex;gesturePhase='locked';candidate='';renderTarot();status().textContent='已锁定，张开手掌抽出。'}else if(gesturePhase==='locked'&&name==='open'&&stable){let idx=deckOffset+lockedIndex;candidate='';drawCard(idx);if(handStream&&tarotSelected.length<3)status().textContent='已抽一张，继续张开手掌选下一张。'}}else{if(fortunePhase==='scan'&&name==='fist'&&now-candidateSince>=140){fortunePhase='shaking';playEffect('shake',true);$('fortuneJar').classList.add('shaking');fortuneMin=h[9].x;fortuneMax=h[9].x;fortuneHold=now;fortuneShake=false;status().textContent='握住了，左右晃动手掌。'}if(fortunePhase==='shaking'&&name==='fist'){fortuneMin=Math.min(fortuneMin,h[9].x);fortuneMax=Math.max(fortuneMax,h[9].x);if(fortuneMax-fortuneMin>.055){fortuneShake=true;status().textContent='摇好了，张开手掌出签。'}}if(fortunePhase==='shaking'&&name==='open'&&now-candidateSince>=140){if(fortuneShake&&now-fortuneHold>300){fortunePhase='done';drawFortune();status().textContent='签已落下，想再抽可点击重新摇签。'}else{fortunePhase='scan';stopShakeEffect();$('fortuneJar').classList.remove('shaking');status().textContent='还没摇够，请握拳并左右晃动。'}}}}
async function handLoop(now=0){if(!handStream||!handsInstance)return;if(!handBusy&&now-lastInference>90&&videoEl().readyState>=2){handBusy=true;lastInference=now;try{await handsInstance.send({image:videoEl()})}catch(e){console.warn(e);stopCamera();panel().classList.remove('hidden');status().textContent='识别中断，请关闭后重试。';return}finally{handBusy=false}}if(handStream)handRAF=requestAnimationFrame(handLoop)}
function stopCamera(){drawHandOverlay(null);stopShakeEffect();handGeneration++;cancelAnimationFrame(handRAF);if(handStream){handStream.getTracks().forEach(t=>t.stop());handStream=null}if(handsInstance){handsInstance.close();handsInstance=null}for(const id of ['cameraVideo','fortuneVideo']){const v=$(id);if(v)v.srcObject=null}for(const id of ['gestureToggle','fortuneGestureToggle']){const b=$(id);if(b){b.disabled=false;b.textContent='开启手势选牌'}}$('fortuneGestureToggle').textContent='开启手势摇签';$('gesturePanel').classList.add('hidden');$('fortuneGesturePanel').classList.add('hidden');gesturePhase='scan';fortunePhase='scan';lockedIndex=null;candidate=''}
$('gestureToggle').onclick=()=>{activeMode='tarot';if(handStream)stopCamera();else startCamera()};$('cameraClose').onclick=stopCamera;
const effectFlip=new Audio('assets/audio/card-flip.wav'),effectShake=new Audio('assets/audio/sticks-shake.wav');effectFlip.volume=.3;effectShake.volume=.55;function playEffect(kind,loop=false){if(!musicOn)return;const a=kind==='flip'?effectFlip:effectShake;a.loop=loop;if(a.paused){a.currentTime=0;a.play().catch(()=>{})}}function stopShakeEffect(){effectShake.pause();effectShake.currentTime=0;effectShake.loop=false}
const fortunes=[['雨水 · 平','云还没散，但雨会停。事情需要时间，不必抢这一步。'],['清明 · 慎','旧事未了，先把误会说清楚，别急着往前冲。'],['立夏 · 吉','局面有起色，可以试着推进，但不要把话说满。'],['芒种 · 中','事情有收获，也有取舍。你不可能样样都要。'],['秋分 · 中','先看清得失再决定，别因为一时情绪站队。'],['大雪 · 慎','现在阻力偏大，收住脚步，等条件更明朗。'],['小满 · 中','还没到收的时候。你现在急，也收不了。'],['立春 · 吉','新事有机会，先动起来，别只等消息。'],['白露 · 平','有些事情开始清楚，但还不适合急着下结论。'],['霜降 · 慎','眼前有阻力，先检查细节，硬推容易出错。'],['惊蛰 · 吉','停着的事开始有动静，机会来了要主动接。'],['冬至 · 平','现在不适合冒进，先把手头的事情收好。']];
function openFortune(){$('reopenFortune').classList.add('hidden');showFortuneTab('fortune');activeMode='fortune';fortunePhase='scan';$('fortuneStage').classList.remove('hidden');$('saveFortune').classList.add('hidden');$('fortuneResult').textContent='心里想一件事，摇一支签。';$('fortuneExit').focus();startCamera()}function closeFortune(){stopCamera();$('fortuneStage').classList.add('hidden');activeMode='tarot'}function drawFortune(){stopShakeEffect();playEffect('shake');let f=fortunes[randomBelow(fortunes.length)],jar=$('fortuneJar'),stick=$('fallingStick');jar.classList.add('shaking');stick.classList.remove('fall');$('fortuneResult').textContent='正在摇签……';setTimeout(()=>{jar.classList.remove('shaking');void stick.offsetWidth;stick.classList.add('fall');$('fortuneResult').textContent='签落下来了……'},350);setTimeout(()=>{if($('fortuneStage').classList.contains('hidden'))return;$('fortuneResult').replaceChildren();let b=document.createElement('b'),p=document.createElement('p');b.textContent=f[0];p.textContent=f[1];$('fortuneResult').append(b,p);$('saveFortune').classList.remove('hidden');document.dispatchEvent(new CustomEvent('night-result',{detail:{kind:'fortune',title:f[0],lines:['阿婆的签'],summary:f[1]}}))},1100)}$('fortuneGestureToggle').onclick=()=>{activeMode='fortune';if(handStream)stopCamera();else startCamera()};$('fortuneCameraClose').onclick=stopCamera;$('fortuneDraw').onclick=drawFortune;$('fortuneReset').onclick=()=>{fortunePhase='scan';candidate='';$('fortuneJar').classList.remove('shaking');$('fallingStick').classList.remove('fall');$('fortuneResult').textContent='心里想一件事，摇一支签。';$('saveFortune').classList.add('hidden');if(handStream)$('fortuneGestureStatus').textContent='握拳并左右晃动，再张开手掌出签。'};$('fortuneExit').onclick=()=>{closeFortune();$('insideStatus').textContent='想再抽一次，可以重新摇签。';$('reopenFortune').classList.remove('hidden')};$('reopenFortune').onclick=openFortune;document.addEventListener('night-pause-gesture',()=>stopCamera());document.addEventListener('night-closing',()=>{cancelAnimationFrame(sceneFade);stopCamera();stopDreamVoice();Object.values(tracks).forEach(a=>a.pause());stopVoice()});

const dreamSymbols=[['掉牙','掉牙','传统解梦里常把掉牙与亲人、变化联系起来；从现实感受看，也可能和失控感、压力有关。想想最近哪件事让你没有把握。'],['牙齿','掉牙','传统解梦常把牙齿变化与亲人或生活变化联系起来；也可以留意最近让你不安的事。'],['蛇','蛇','传统解梦中蛇的含义随情境而变，可能指变化、警惕或纠缠。蛇是否靠近你、你有没有害怕，是理解这个梦的重要细节。'],['水','水','水常被看作情绪的象征。水清或浑、平静或汹涌，会改变传统解读的方向。'],['飞','飞翔','飞翔常被理解为想挣脱限制；如果飞得吃力，也可能反映你担心自己撑不住。'],['考试','考试','梦见考试常和被评价、准备不足或对结果的担忧有关。'],['追','被追赶','被追赶常被理解为你在回避某件事；梦里追你的人和你最终有没有逃开，值得留意。'],['火','火','火在传统象征里既有兴旺、行动的意思，也可能提醒情绪或冲突正在升温。'],['死','死亡','传统解梦常把梦中的死亡解释为结束或变化，不必把它当成现实预兆。'],['钱','金钱','金钱常和安全感、得失或资源有关。是捡到、丢失还是花钱，会影响解读。'],['雨','下雨','雨可能象征情绪释放；如果梦里淋雨让你难受，也可能反映近期压力。'],['房','房屋','房屋常被看作生活状态的象征。陌生、破旧或正在修理，都值得结合细节理解。'],['猫','猫','猫可联系直觉、独立或警惕。梦里的猫是否亲近你，比单独的猫字更重要。'],['狗','狗','传统象征中狗常与关系或守护有关；如果梦里被追咬，也可能对应现实中的不信任。']];
