 function chooseMood(){heading('小满的梦本 · 1 / 2','小满合上笔，抬头看你：“梦里那一刻，你是什么感觉？”');choices(['害怕 / 不安','难过 / 委屈','开心 / 安心','说不上来'],v=>{mood=v;chooseEnding()})}
 function chooseEnding(){heading('小满的梦本 · 2 / 2','“那后来呢？这个梦，最后停在了哪里？”');choices(['事情有了转机','还没解决就醒了','记不清了'],v=>{ending=v;reveal()});const back=document.createElement('button');back.type='button';back.className='journey-back';back.textContent='← 改一改刚才的回答';back.onclick=chooseMood;box.append(back)}
 function reveal(){interpretDreamCore();const intro=document.createElement('div');intro.className='dream-reflection';const title=document.createElement('b');title.textContent='小满翻开了梦本';const p=document.createElement('p');const feelings={'害怕 / 不安':'你记得的是不安','难过 / 委屈':'你记得的是难过','开心 / 安心':'你记得的是安心','说不上来':'那种感觉一时说不上来'};const ends={'事情有了转机':'梦里后来有了转机，这个细节也值得留着。','还没解决就醒了':'事情还没结束你就醒了，难怪醒来还会记挂。','记不清了':'结尾记不清也没关系，记得的部分已经足够。'};p.textContent='“'+feelings[mood]+'；'+ends[ending]+' 我们先看看，你的梦里出现了什么。”';intro.append(title,p);out.prepend(intro);const again=document.createElement('button');again.type='button';again.className='journey-back';again.textContent='重新回答小满的问题';again.onclick=()=>{out.replaceChildren(box);chooseMood()};out.append(again);document.dispatchEvent(new Event('night-dream-updated'));paginateDreamResult(out);void 0}
