$('dreamInterpret').onclick=interpretDream;$('dreamExit').onclick=()=>{closeDream();$('insideStatus').textContent='还想讲梦，可以再翻开本子。';$('reopenDream').classList.remove('hidden')};$('reopenDream').onclick=openDream;let dreamVoiceWanted=false,dreamVoiceRestart=null,dreamVoiceFailures=0;function stopDreamVoice(){setSpeaking('dream',false);dreamVoiceWanted=false;clearTimeout(dreamVoiceRestart);const r=window.dreamRecognition;window.dreamRecognition=null;if(r){try{r.stop()}catch(e){}}$('dreamVoice').textContent='语音说梦';$('dreamVoiceStatus').textContent='已停止，文字可以继续编辑。'}
$('dreamVoice').onclick=()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){$('dreamVoiceStatus').textContent='当前浏览器不支持语音输入，可以直接打字。';return}if(dreamVoiceWanted){stopDreamVoice();return}dreamVoiceWanted=true;setSpeaking('dream',true);dreamVoiceFailures=0;let sessionBase=$('dreamInput').value.trim();const rec=new Speech();window.dreamRecognition=rec;rec.lang='zh-CN';rec.continuous=true;rec.interimResults=true;let fatal=false;rec.onstart=()=>{$('dreamVoice').textContent='停止录音';$('dreamVoiceStatus').textContent='正在听，你可以停顿后继续说。'};rec.onresult=e=>{dreamVoiceFailures=0;let words='';for(let i=0;i<e.results.length;i++){const part=e.results[i][0]?.transcript||'';words+=part}if(words){const sep=sessionBase&&!/[，。！？、\s]$/.test(sessionBase)?'，':'';$('dreamInput').value=sessionBase+sep+words}};rec.onerror=e=>{if(e.error==='no-speech'){dreamVoiceFailures++;$('dreamVoiceStatus').textContent='刚才没有听清，正在继续听……';return}fatal=true;dreamVoiceWanted=false;setSpeaking('dream',false);const messages={'not-allowed':'麦克风权限未开启，请在浏览器设置中允许。','service-not-allowed':'浏览器的语音服务不可用，请直接打字。','network':'语音服务网络连接失败，请检查网络或直接打字。','audio-capture':'没有找到麦克风，请检查设备。'};$('dreamVoiceStatus').textContent=messages[e.error]||'语音识别中断，请重新点击或直接打字。';$('dreamVoice').textContent='语音说梦'};rec.onend=()=>{if(window.dreamRecognition!==rec)return;if(!dreamVoiceWanted||fatal){window.dreamRecognition=null;$('dreamVoice').textContent='语音说梦';return}sessionBase=$('dreamInput').value.trim();if(dreamVoiceFailures>=3){dreamVoiceWanted=false;setSpeaking('dream',false);window.dreamRecognition=null;$('dreamVoice').textContent='语音说梦';$('dreamVoiceStatus').textContent='暂时没有听清，点击语音说梦可以继续。';return}$('dreamVoiceStatus').textContent='正在继续听……';dreamVoiceRestart=setTimeout(()=>{if(!dreamVoiceWanted||window.dreamRecognition!==rec)return;try{rec.start()}catch(e){dreamVoiceWanted=false;setSpeaking('dream',false);window.dreamRecognition=null;$('dreamVoice').textContent='语音说梦';$('dreamVoiceStatus').textContent='语音识别暂停，请点击语音说梦继续。'}},350)};try{rec.start()}catch(e){dreamVoiceWanted=false;setSpeaking('dream',false);window.dreamRecognition=null;$('dreamVoice').textContent='语音说梦';$('dreamVoiceStatus').textContent='语音识别无法启动，请检查权限或直接打字。'}};
