{const sc=$('streetScroll');let down=false,startX=0,startScroll=0,moved=false;sc.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;down=true;moved=false;startX=e.clientX;startScroll=sc.scrollLeft});window.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-startX;if(Math.abs(dx)>6)moved=true;if(moved){sc.scrollLeft=startScroll-dx;sc.classList.add('dragging-street')}});window.addEventListener('pointerup',()=>{if(!down)return;down=false;sc.classList.remove('dragging-street');if(moved){const cancel=e=>{e.preventDefault();e.stopImmediatePropagation()};sc.addEventListener('click',cancel,{capture:true,once:true});setTimeout(()=>sc.removeEventListener('click',cancel,true),100)}})}

// 小六壬：采用农历月日时各从一数起的常见掌诀。
const sixNames=['大安','留连','速喜','赤口','小吉','空亡'];const sixText=['大安，主安稳。你问的事有基础，暂时不用急着换方向。只是进展偏慢，想立刻见结果，恐怕还得等等。','留连，主拖延。这事还缠着，一时半会儿定不下来。该问的人再问清楚，等的时候也给自己留个期限。','速喜，主消息来得快。事情可能很快有动静，机会到了就接住；但消息是消息，最后能不能成，还得看后续。','赤口，主口舌。眼下容易因为一句话闹出误会。重要的事当面说清，答应之前先把条件听完。','小吉，主小有所得。这事有转机，能往前走一段，但未必一下就到你想要的结果。先把眼前能做的做好。','空亡，主落空或悬而未定。这次可能得不到你盼的答复，眼前条件也还不齐。别只押这一条路，备个后手。'];const sixDetails=[['大安是什么意思','大安是六神里的安稳之象。它说的是局面暂时稳得住，不等于什么都不用做。','问工作或考试','按原计划准备，适合稳步推进；如果在等消息，耐心可以有，也要记得适时跟进。','问感情','关系有继续相处的基础，但对方未必马上表态。别把沉默直接当成承诺。'],['留连是什么意思','留连有停留、反复之意。事没有彻底结束，也不容易马上拍板。','问工作或考试','材料、流程或答复可能来回修改；问清截止时间，别无限期地等。','问感情','有牵挂，也可能有没说开的地方。反复猜不如找个合适的时候问明白。'],['速喜是什么意思','速喜指消息或变化来得较快。它偏向喜讯，但不是对最终结果的保证。','问工作或考试','可能较快收到通知或进展。留意邮箱和电话，提前准备要交的材料。','问感情','适合主动联系或把想法说出来，但别只凭一时热络就替对方下结论。'],['赤口是什么意思','赤口多与口舌、分歧相联系。事情未必坏，麻烦常出在表达和误会。','问工作或考试','看清要求，重要信息留记录；遇到不同意见，先确认事实再回应。','问感情','小事容易说重。把真实在意的事讲清楚，别靠试探逼对方回答。'],['小吉是什么意思','小吉是有利但有限的好兆头，通常指事情有进展，需要继续经营。','问工作或考试','可以争取机会，但还要看实力和准备；先拿到眼前的小成果。','问感情','相处有好的一面，别急着追问结果。看对方是否愿意持续行动。'],['空亡是什么意思','空亡多解作落空、暂时无着落。它提醒你正视不确定，不是给事情盖棺定论。','问工作或考试','眼下可能没有答复，或原计划难以兑现；继续跟进，同时准备备选。','问感情','如果一直只有你一个人在推进，先停下来看看对方有没有回应。']];const hours=['子时 23:00—00:59','丑时 01:00—02:59','寅时 03:00—04:59','卯时 05:00—06:59','辰时 07:00—08:59','巳时 09:00—10:59','午时 11:00—12:59','未时 13:00—14:59','申时 15:00—16:59','酉时 17:00—18:59','戌时 19:00—20:59','亥时 21:00—22:59'];function setupLiuren(){$('lunarMonth').add(new Option('请选择农历月',''));$('lunarDay').add(new Option('请选择农历日',''));for(let i=1;i<=12;i++)$('lunarMonth').add(new Option('农历 '+i+' 月',i));for(let i=1;i<=30;i++)$('lunarDay').add(new Option('农历 '+i+' 日',i));hours.forEach((h,i)=>$('lunarHour').add(new Option(h,i+1)));$('lunarHour').value=String(Math.floor(((new Date().getHours()+1)%24)/2)+1);try{const parts=new Intl.DateTimeFormat('en-u-ca-chinese',{month:'numeric',day:'numeric'}).formatToParts(new Date());const m=parseInt(parts.find(x=>x.type==='month').value),d=parseInt(parts.find(x=>x.type==='day').value);if(m>=1&&m<=12)$('lunarMonth').value=String(m);if(d>=1&&d<=30)$('lunarDay').value=String(d)}catch(e){}}setupLiuren();function showFortuneTab(which){const isSign=which==='fortune';if(handStream||handsInstance||$('fortuneGestureToggle').disabled)stopCamera();$('fortuneDrawPanel').classList.toggle('hidden',!isSign);$('liurenPanel').classList.toggle('hidden',isSign);$('fortuneTab').setAttribute('aria-selected',String(isSign));$('liurenTab').setAttribute('aria-selected',String(!isSign))}$('fortuneTab').onclick=()=>{showFortuneTab('fortune');activeMode='fortune';startCamera()};$('liurenTab').onclick=()=>showFortuneTab('liuren');$('liurenCalculate').onclick=()=>{const m=Number($('lunarMonth').value),d=Number($('lunarDay').value),h=Number($('lunarHour').value);if(!m||!d){$('liurenResult').textContent='先选好农历月和日，再起课。';return}const mi=(m-1)%6,di=(mi+d-1)%6,hi=(di+h-1)%6;const out=$('liurenResult');out.replaceChildren();let b=document.createElement('b'),p=document.createElement('p'),small=document.createElement('small');b.textContent=sixNames[hi];p.textContent=sixText[hi];small.textContent=`月落${sixNames[mi]} → 日落${sixNames[di]} → 时落${sixNames[hi]}。`;out.append(b,p,small);const detail=sixDetails[hi];for(let i=0;i<detail.length;i+=2){let h=document.createElement('h3'),q=document.createElement('p');h.textContent=detail[i];q.textContent=detail[i+1];out.append(h,q)}let note=document.createElement('small');note.textContent='以上为民俗掌诀的通俗解说，结合你问的事看，不代表确定结果。';out.append(note);$('saveLiuren').classList.remove('hidden');document.dispatchEvent(new CustomEvent('night-result',{detail:{kind:'liuren',title:sixNames[hi]+' · 小六壬',lines:[`月落${sixNames[mi]} · 日落${sixNames[di]} · 时落${sixNames[hi]}`],summary:sixText[hi]}}))};

